export const UpdateScriptBody = zod.object({
  "hook": zod.string().min(1).max(updateScriptBodyHookMax).optional(),
  "narration": zod.string().min(1).max(updateScriptBodyNarrationMax).optional(),
  "soundMusic": zod.string().max(updateScriptBodySoundMusicMax).optional(),
  "cta": zod.string().max(updateScriptBodyCtaMax).optional(),
  "scenes": zod.array(zod.object({
  "sequence": zod.number().int().min(1),
  "narration": zod.string(),
  "visualInstructions": zod.string(),
  "onScreenText": zod.string(),
  "soundSuggestion": zod.string()
})).max(updateScriptBodyScenesMax).optional()
})




export const UpdateScriptResponse = zod.object({
  "id": zod.string().uuid(),
  "projectId": zod.string().uuid(),
  "ideaId": zod.string().uuid(),
  "hook": zod.string(),
  "narration": zod.string(),
  "soundMusic": zod.string(),
  "cta": zod.string(),
  "status": zod.enum(['DRAFT', 'APPROVED']),
  "scenes": zod.array(zod.object({
  "sequence": zod.number().int().min(1),
  "narration": zod.string(),
  "visualInstructions": zod.string(),
  "onScreenText": zod.string(),
  "soundSuggestion": zod.string()
}).and(zod.object({
  "id": zod.string().uuid(),
  "scriptId": zod.string().uuid()
}))),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})


/**
 * @summary Approve a script after editing
 */
